<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50 pb-28">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'Account' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali ke Akun"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>

				<div class="flex min-w-0 flex-1 flex-col justify-center">
					<span class="min-w-0 truncate font-medium text-ui-ink-gray-900">Ubah Kata Sandi</span>
				</div>
			</div>
		</div>

		<div class="px-5 pt-5">
			<div class="bg-ui-surface rounded-[1.75rem] px-6 py-6 shadow-sm">
				<!-- Memuat status awal -->
				<div
					v-if="memuat"
					class="flex items-center justify-center gap-2 py-6 text-sm text-ui-ink-gray-600"
				>
					<Spinner />
					<span>Memuat...</span>
				</div>

				<!-- Belum ada permintaan -->
				<div v-else-if="status === 'none' || status === 'expired'" class="space-y-4">
					<p class="text-sm text-ui-ink-gray-700 leading-relaxed">
						Perubahan kata sandi harus disetujui administrator lebih dulu. Tekan tombol
						di bawah untuk mengirim permintaan, lalu tunggu persetujuan.
					</p>
					<p
						v-if="status === 'expired'"
						class="px-4 py-3 bg-ui-surface-amber-50 border border-ui-line-amber-200 rounded-[0.875rem] text-ui-ink-amber-800 text-sm"
					>
						Permintaan sebelumnya sudah kedaluwarsa. Silakan ajukan ulang.
					</p>
					<button
						type="button"
						@click="ajukan"
						:disabled="loading"
						class="w-full py-4 bg-primary text-ui-onPrimary rounded-[1.25rem] font-semibold text-base hover:bg-primary-hover focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-colors disabled:opacity-70"
					>
						{{ loading ? 'Mengirim...' : 'Ajukan Perubahan Kata Sandi' }}
					</button>
				</div>

				<!-- Menunggu persetujuan -->
				<div v-else-if="status === 'pending'" class="space-y-4">
					<div
						class="px-5 py-4 bg-ui-surface-amber-50 border border-ui-line-amber-200 rounded-[1.25rem] text-ui-ink-amber-800 text-sm leading-relaxed"
					>
						<p class="font-semibold mb-1">Menunggu persetujuan administrator</p>
						<p>
							Anda akan menerima notifikasi begitu permintaan disetujui. Halaman ini
							boleh ditutup — permintaan Anda tetap tersimpan.
						</p>
					</div>

					<div
						v-if="autoAktif"
						class="flex items-center justify-center gap-2 text-sm text-ui-ink-gray-600"
						aria-live="polite"
					>
						<Spinner />
						<span>Memeriksa status otomatis...</span>
					</div>

					<button
						type="button"
						@click="cekManual"
						:disabled="loading"
						class="w-full py-4 border border-ui-heading text-ui-heading rounded-[1.25rem] font-semibold text-base hover:bg-ui-surface-gray-50 focus:outline-none transition-colors disabled:opacity-70"
					>
						{{ loading ? 'Memeriksa...' : 'Cek Sekarang' }}
					</button>
				</div>

				<!-- Disetujui — isi kata sandi baru -->
				<form v-else-if="status === 'approved'" @submit.prevent="simpan" class="space-y-4">
					<div
						class="px-5 py-3 bg-ui-surface-green-50 border border-ui-line-green-200 rounded-[1.25rem] text-ui-ink-green-800 text-sm"
					>
						Permintaan disetujui. Atur kata sandi baru dalam 1 jam ke depan.
					</div>

					<div class="relative">
						<input
							v-model="newPassword"
							:type="showPassword ? 'text' : 'password'"
							autocomplete="new-password"
							placeholder="Kata sandi baru"
							required
							class="w-full pl-5 pr-12 py-3.5 bg-transparent border border-ui-heading rounded-[1.25rem] text-ui-ink placeholder-ui-ink-gray-600 focus:outline-none focus:ring-1 focus:ring-ui-heading"
						/>
						<button
							type="button"
							@click="showPassword = !showPassword"
							:aria-label="
								showPassword ? 'Sembunyikan kata sandi' : 'Tampilkan kata sandi'
							"
							class="absolute inset-y-0 right-0 flex items-center pr-4 text-ui-heading"
						>
							<svg
								v-if="showPassword"
								xmlns="http://www.w3.org/2000/svg"
								width="20"
								height="20"
								viewBox="0 0 24 24"
								fill="none"
								stroke="currentColor"
								stroke-width="1.75"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<path d="M9.88 9.88a3 3 0 1 0 4.24 4.24" />
								<path
									d="M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68"
								/>
								<path
									d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61"
								/>
								<line x1="2" y1="2" x2="22" y2="22" />
							</svg>
							<svg
								v-else
								xmlns="http://www.w3.org/2000/svg"
								width="20"
								height="20"
								viewBox="0 0 24 24"
								fill="none"
								stroke="currentColor"
								stroke-width="1.75"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
								<circle cx="12" cy="12" r="3" />
							</svg>
						</button>
					</div>

					<input
						v-model="confirmPassword"
						:type="showPassword ? 'text' : 'password'"
						autocomplete="new-password"
						placeholder="Ulangi kata sandi baru"
						required
						class="w-full px-5 py-3.5 bg-transparent border border-ui-heading rounded-[1.25rem] text-ui-ink placeholder-ui-ink-gray-600 focus:outline-none focus:ring-1 focus:ring-ui-heading"
					/>

					<button
						type="submit"
						:disabled="loading"
						class="w-full py-4 bg-primary text-ui-onPrimary rounded-[1.25rem] font-semibold text-base hover:bg-primary-hover focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary transition-colors disabled:opacity-70"
					>
						{{ loading ? 'Menyimpan...' : 'Simpan Kata Sandi' }}
					</button>
				</form>

				<!-- Ditolak -->
				<div v-else-if="status === 'rejected'" class="space-y-4">
					<div
						class="px-5 py-4 bg-ui-surface-red-50 border border-ui-line-red-200 rounded-[1.25rem] text-ui-ink-red-700 text-sm leading-relaxed"
					>
						<p class="font-semibold mb-1">Permintaan ditolak</p>
						<p v-if="catatan">{{ catatan }}</p>
						<p v-else>Hubungi administrator untuk informasi lebih lanjut.</p>
					</div>
					<button
						type="button"
						@click="ajukan"
						:disabled="loading"
						class="w-full py-4 bg-primary text-ui-onPrimary rounded-[1.25rem] font-semibold text-base hover:bg-primary-hover focus:outline-none transition-colors disabled:opacity-70"
					>
						{{ loading ? 'Mengirim...' : 'Ajukan Ulang' }}
					</button>
				</div>

				<!-- Selesai — status lokal, dipasang tepat setelah menyimpan -->
				<div v-else-if="status === 'done'" class="space-y-4">
					<div
						class="px-5 py-4 bg-ui-surface-green-50 border border-ui-line-green-200 rounded-[1.25rem] text-ui-ink-green-800 text-sm leading-relaxed"
					>
						<p class="font-semibold mb-1">Kata sandi berhasil diubah</p>
						<p>
							Sesi Anda di perangkat lain sudah dikeluarkan. Gunakan kata sandi baru
							saat masuk berikutnya.
						</p>
					</div>
					<p
						class="px-5 py-3 bg-ui-surface-gray-100 border border-ui-line-gray-200 rounded-[1.25rem] text-ui-ink-gray-700 text-sm text-center leading-relaxed"
					>
						Perubahan kata sandi berikutnya baru bisa diajukan setelah
						<span class="font-medium">12 jam</span>.
					</p>
				</div>

				<!-- Masih dalam jeda setelah penggantian terakhir -->
				<div v-else-if="status === 'cooldown'" class="space-y-4">
					<div
						class="px-5 py-4 bg-ui-surface-gray-100 border border-ui-line-gray-200 rounded-[1.25rem] text-ui-ink-gray-700 text-sm leading-relaxed"
					>
						<p class="font-semibold mb-1 text-ui-heading">Belum bisa diajukan lagi</p>
						<p>
							Kata sandi Anda baru saja diubah. Perubahan berikutnya bisa diajukan
							<template v-if="sisa"
								>dalam <span class="font-medium">{{ sisa }}</span> lagi.</template
							>
							<template v-else>beberapa saat lagi.</template>
						</p>
					</div>
				</div>

				<div
					v-if="errorMessage"
					role="alert"
					class="mt-4 px-4 py-3 bg-ui-surface-red-50 border border-ui-line-red-200 rounded-[0.875rem] text-ui-ink-red-700 text-sm text-center"
				>
					{{ errorMessage }}
				</div>
			</div>
		</div>

		<BottomNav />
	</div>
</template>

<script setup>
import { h, onMounted, ref, watch } from 'vue'
import { call } from 'frappe-ui'
import BottomNav from '../components/BottomNav.vue'
import { useAutoCheck } from '../composables/useAutoCheck'

const API = 'juragan.api.portal.password_reset'

const Spinner = () =>
	h(
		'svg',
		{
			class: 'animate-spin',
			xmlns: 'http://www.w3.org/2000/svg',
			width: 16,
			height: 16,
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': 2,
			'stroke-linecap': 'round',
		},
		[h('path', { d: 'M21 12a9 9 0 1 1-6.219-8.56' })]
	)

const status = ref('none')
const catatan = ref('')
const sisa = ref('')
const newPassword = ref('')
const confirmPassword = ref('')
const showPassword = ref(false)
const memuat = ref(true)
const loading = ref(false)
const errorMessage = ref('')

function friendlyError(err) {
	const raw = err?.messages?.[0] || err?._error_message || err?.message || String(err || '')
	const text = String(raw)
	if (/failed to fetch|network|load failed/i.test(text)) {
		return 'Tidak dapat terhubung ke server. Coba lagi.'
	}
	if (/too many requests|rate limit/i.test(text)) {
		return 'Terlalu banyak percobaan. Coba lagi satu jam berikutnya.'
	}
	return (
		text
			.replace(/<[^>]*>/g, ' ')
			.replace(/\s+/g, ' ')
			.trim() || 'Terjadi kesalahan. Coba lagi.'
	)
}

async function muatStatus() {
	const hasil = await call(`${API}.my_reset_status`)
	status.value = hasil?.status || 'none'
	catatan.value = hasil?.catatan || ''
	sisa.value = hasil?.sisa || ''
}

// Selama menunggu persetujuan, status dicek sendiri supaya form kata sandi
// muncul otomatis begitu admin menyetujui.
const {
	aktif: autoAktif,
	start: mulaiAutoCek,
	stop: hentikanAutoCek,
} = useAutoCheck(muatStatus, {
	onError(error) {
		// Gangguan jaringan sesaat tidak perlu diteriakkan tiap 15 detik; kuota
		// habis harus menghentikan polling daripada terus ditolak.
		const pesan = friendlyError(error)
		if (/terlalu banyak percobaan/i.test(pesan)) {
			hentikanAutoCek()
			errorMessage.value = pesan
		}
	},
})

watch(status, (nilai) => {
	if (nilai === 'pending') mulaiAutoCek()
	else hentikanAutoCek()
})

onMounted(async () => {
	try {
		await muatStatus()
	} catch (error) {
		errorMessage.value = friendlyError(error)
	} finally {
		memuat.value = false
	}
})

async function ajukan() {
	errorMessage.value = ''
	loading.value = true
	try {
		const hasil = await call(`${API}.request_reset_for_self`)
		status.value = hasil?.status || 'pending'
		catatan.value = ''
	} catch (error) {
		errorMessage.value = friendlyError(error)
	} finally {
		loading.value = false
	}
}

async function cekManual() {
	errorMessage.value = ''
	loading.value = true
	try {
		await muatStatus()
		// Masih menunggu tapi polling sudah berhenti (halaman lama terbuka) —
		// hidupkan lagi. Watcher `status` tidak menolong karena nilainya sama.
		if (status.value === 'pending' && !autoAktif) mulaiAutoCek()
	} catch (error) {
		errorMessage.value = friendlyError(error)
	} finally {
		loading.value = false
	}
}

async function simpan() {
	errorMessage.value = ''

	if (newPassword.value !== confirmPassword.value) {
		errorMessage.value = 'Konfirmasi kata sandi tidak sama.'
		return
	}

	loading.value = true
	try {
		await call(`${API}.submit_my_new_password`, {
			new_password: newPassword.value,
			confirm_password: confirmPassword.value,
		})
		newPassword.value = ''
		confirmPassword.value = ''
		status.value = 'done'
	} catch (error) {
		errorMessage.value = friendlyError(error)
	} finally {
		loading.value = false
	}
}
</script>
